respBody:
html {
	font-family: Roboto, "Noto Sans", "Noto Sans SC", FontAwesome, "Glyphicons Halflings", sans-serif !important;
	font-size: 14px;
	--portal-font-name: Roboto;
	color: #4A4A4A;
}

html.app-core-ui {
	font-family: Inter, "Noto Sans", "Noto Sans SC", FontAwesome, "Glyphicons Halflings", sans-serif !important;
	--portal-font-name: Inter;
	color: #333;
}

html.app-core-ui.app-mobile {
	font-size: 16px;
}

body {
	font-family: inherit !important;
	font-size: inherit !important;
}

body.loading-progress *, *:before, *:after {
	box-sizing: border-box;
}

body.loading-progress html, body.loading-progress {
	margin: 0;
	padding: 0;
	height: 100%;
	width: 100%;
}

body.loading-progress {
	background-color: #FFF;
	min-height: 100%;
	padding-bottom: 0;
	line-height: 1.5;
}

body.loading-progress .app-page {
	height: 100%;
	display: -webkit-box;
	display: -moz-box;
	display: -ms-flexbox;
	display: -webkit-flex;
	display: flex;
	-webkit-flex-flow: column;
	flex-flow: column;
}

body.loading-progress .visible-xs,
body.loading-progress .visible-sm,
body.loading-progress .visible-md,
body.loading-progress .visible-lg {
	display: none !important;
}

body.loading-progress .app-page-header {
	background-color: #F5F5F5;
	border-left: 1px solid #C8C8C8;
	border-right: 1px solid #C8C8C8;
	border-bottom: 1px solid #C8C8C8;
	min-height: 50px;
	height: 50px;
	clear: both;
}

.app-core-ui body.loading-progress .app-page-header {
	background-color: #F5F3F2;
	border-left: 1px solid #C7C7C7;
	border-right: 1px solid #C7C7C7;
	border-bottom: 1px solid #C7C7C7;
}

.app-core-ui.app-framed body.loading-progress .app-page-header {
	background-color: #FFF;
	border-left: none;
	border-right: none;
}

body.loading-progress .app-page-header > .loading {
	font-size: 1.125rem;
	display: flex;
	position: relative;

}

body.loading-progress .app-page-header > .loading > span {
	padding: 11px 11px 11px 11px;
}

body.loading-progress .app-page-body {
	display: -webkit-box;
	display: -moz-box;
	display: -ms-flexbox;
	display: -webkit-flex;
	display: flex;
	-webkit-flex-flow: row nowrap;
	flex-flow: row nowrap;
	width: 100%;
	-webkit-flex: 1 0 auto;
	-ms-flex: 1 0 auto;
	flex: 1 0 auto;
	-webkit-align-items: stretch;
	align-items: stretch;
	background-color: #fff;
}

body.loading-progress .app-page-body-content {
	display: -webkit-box;
	display: -moz-box;
	display: -ms-flexbox;
	display: -webkit-flex;
	display: flex;
	-webkit-flex-flow: column;
	flex-flow: column;
	-webkit-flex: 1 1 auto;
	-ms-flex: 1 1 auto;
	flex: 1 1 auto;
	position: relative;
	overflow: hidden;
}

body.loading-progress .app-page-body .center-content {
	display: -webkit-box;
	display: -moz-box;
	display: -ms-flexbox;
	display: -webkit-flex;
	display: flex;

	width: 100%;
	-webkit-flex: 1 0 auto;
	-ms-flex: 1 0 auto;
	flex: 1 0 auto;
	flex-flow: column;
	-webkit-justify-content: center;
	justify-content: center;
	-webkit-align-items: center;
	align-items: center;
}

body.loading-progress .app-page-body .center-content .content-wrapper {
	position: relative;
	width: 280px;
}

body.loading-progress .app-page-body .center-content .content-wrapper .app-text-container {
	text-align: center;
	position: absolute;
	top: 122px;
	width: 100%;
}

body.loading-progress .app-page-body .center-content .content-wrapper .app-text-container span {
	display: inline-block;
	margin-top: 10px;
	width: 100%;
}

body.loading-progress .app-page-body .center-content .content-wrapper .animated-logo {
	width: 122px;
	height: 122px;
	margin: 0 auto;
	color: #F78E1E;
}

.app-core-ui body.loading-progress .app-page-body .center-content .content-wrapper .animated-logo {
	color: #3366DD;
}

body.loading-progress .app-page-body .animated-logo .spinner-icon {
	aspect-ratio: 1;
}

body.loading-progress .app-page-body .animated-logo .spinner-circle {
	fill: none;
	stroke: currentColor;
	stroke-width: 9.4;
	stroke-linecap: round;
	/* 360 is the circumference (2 * pi * 57.3) */
	stroke-dasharray: 360;
	transform-origin: center;
	transform-box: fill-box;
	animation: app-spin-pulse 1.6s linear infinite;
}

@keyframes app-spin-pulse {
	0% {
		stroke-dashoffset: 360;
		transform: rotate(0deg);
	}
	50% {
		stroke-dashoffset: 90;
		transform: rotate(270deg);
	}
	100% {
		stroke-dashoffset: 360;
		transform: rotate(720deg);
	}
}

body.loading-progress .height-100 {
	height: 100% !important;
}

body.loading-progress .width-100 {
	width: 100% !important;
}

body.loading-progress {
	height: 100vh;
}

body.loading-progress > div.app-h-100 {
	display: none;
}

body.embedded-mode.loading-progress .app-page-header {
	border-top: 1px solid #C8C8C8;
	height: 51px;
	min-height: 51px;
}

body.embedded-mode.loading-progress .app-page-body-main-wrapper {
	border-left: 1px solid #C8C8C8;
	border-right: 1px solid #C8C8C8;
	border-bottom: 1px solid #C8C8C8;
}

@-webkit-keyframes rotate {
	0% {
		-webkit-transform: rotateZ(0deg);
		transform: rotateZ(0deg);
	}
	100% {
		-webkit-transform: rotateZ(360deg);
		transform: rotateZ(360deg);
	}
}

@keyframes rotate {
	0% {
		-webkit-transform: rotateZ(0deg);
		transform: rotateZ(0deg);
	}
	100% {
		-webkit-transform: rotateZ(360deg);
		transform: rotateZ(360deg);
	}
}

@-webkit-keyframes pulsate {
	from {
		-webkit-transform: scale3d(1, 1, 1);
		transform: scale3d(1, 1, 1);
	}

	50% {
		-webkit-transform: scale3d(0.85, 0.85, 0.85);
		transform: scale3d(0.85, 0.85, 0.85);
	}

	to {
		-webkit-transform: scale3d(1, 1, 1);
		transform: scale3d(1, 1, 1);
	}
}

@keyframes pulsate {
	from {
		-webkit-transform: scale3d(1, 1, 1);
		transform: scale3d(1, 1, 1);
	}

	50% {
		-webkit-transform: scale3d(0.85, 0.85, 0.85);
		transform: scale3d(0.85, 0.85, 0.85);
	}

	to {
		-webkit-transform: scale3d(1, 1, 1);
		transform: scale3d(1, 1, 1);
	}
}

@-webkit-keyframes slideInLeft {
	from {
		-webkit-transform: translate3d(-100%, 0, 0);
		transform: translate3d(-100%, 0, 0);
		visibility: visible;
	}

	to {
		-webkit-transform: translate3d(0, 0, 0);
		transform: translate3d(0, 0, 0);
	}
}

@keyframes slideInLeft {
	from {
		-webkit-transform: translate3d(-100%, 0, 0);
		transform: translate3d(-100%, 0, 0);
		visibility: visible;
	}

	to {
		-webkit-transform: translate3d(0, 0, 0);
		transform: translate3d(0, 0, 0);
	}
}

.loading-slide-in-left {
	-webkit-animation-name: slideInLeft;
	animation-name: slideInLeft;
	-webkit-animation-duration: 0.5s;
	animation-duration: 0.5s;
	-webkit-animation-fill-mode: both;
	animation-fill-mode: both;
}

.pulsate-animation {
	animation: pulsate 1.5s infinite;
}

(function() {
	const isInIframe = function () {
		return !!window.frameElement && window.frameElement.nodeName === "IFRAME";
	};

	const isMobile = function () {
		return /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);
	};

	const useCoreUi = function () {
		return localStorage.getItem('portal-cority-ui') === 'true';
	};

	const initUiStyles = function() {
		const html = document.querySelector('html');
		html.classList.toggle('app-mobile', isMobile());
		html.classList.toggle('app-core-ui', useCoreUi());
		html.classList.toggle('app-framed', isInIframe());
	}

	const addPreloadTemplateToBody = function () {
		let template =
			'<div class="app-page-header">' +
				'<div class="loading">' +
					'<span class="loading-slide-in-left">' + 'Loading...' + '</span>' +
				'</div>' +
			'</div>' +
			'<div class="app-page-body app-page-body-main-wrapper">' +
				'<div class="app-page-body-content">' +
					'<div class="center-content">' +
						'<div class="content-wrapper">' +
							'<div class="animated-logo">' +
								'<svg class="spinner-icon" viewBox="0 0 124 124">' +
									'<circle class="spinner-circle" cx="62" cy="62" r="57.3" />' +
								'</svg>' +
							'</div>' +
							'<div class="app-text-container">' +
								'<span id="app-progress-text"></span>' +
								'<span id="app-message-text"></span>' +
							'</div>' +
						'</div>' +
					'</div>' +
				'</div>' +
			'</div>';
		let divElement = document.createElement('div');
		divElement.className = 'app-page preload-page height-100 width-100';
		divElement.innerHTML = template;
		document.body.appendChild(divElement);
	};

	initUiStyles();
	addPreloadTemplateToBody();

})();

